input.script:
var recipe = __data("Recipe")[0];
return {
  ingredients: recipe.recipeIngredient,
  totalTime: recipe.totalTime,
  prepTime: recipe.prepTime,
  cookTime: recipe.cookTime,
  ratingValue: recipe.aggregateRating.ratingValue,
  ratingCount: recipe.aggregateRating.ratingCount
};

var scripts = document.querySelectorAll('script[type="application/ld+json"]');
for (var i = 0; i < scripts.length; i++) {
  var data = JSON.parse(scripts[i].textContent);
  if (data['@type'] === 'Recipe' || (Array.isArray(data['@type']) && data['@type'].includes('Recipe'))) {
    return data.recipeIngredient;
  }
}
return 'not found';

var scripts = document.querySelectorAll('script[type="application/ld+json"]');
var results = [];
for (var i = 0; i < scripts.length; i++) {
  try {
    var data = JSON.parse(scripts[i].textContent);
    if (data['@type']) results.push(data['@type']);
  } catch(e) {}
}
return { count: scripts.length, types: results };
